<script setup lang="ts">
import {computed,nextTick,onMounted,ref} from 'vue'
import {Plus,RefreshCw,Save,Search,Trash2,X} from 'lucide-vue-next'
import {api,datetime,key} from '../api/account'
import type {HelpArticle,HelpArticleInput} from '../api/help'
const emit=defineEmits<{notify:[message:string]}>()
const items=ref<HelpArticle[]>([]),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),draft=ref<(HelpArticleInput&{id:string})|null>(null),deleting=ref(''),titleInput=ref<HTMLInputElement|null>(null)
const matches=computed(()=>items.value.filter(p=>(p.title+'\n'+p.content).toLowerCase().includes(query.value.trim().toLowerCase())))
const published=computed(()=>items.value.filter(p=>p.enabled).length)
async function load(){if(loading.value)return;loading.value=true;error.value='';try{items.value=await api<HelpArticle[]>('/admin/help-articles')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function edit(p?:HelpArticle){deleting.value='';error.value='';draft.value=p?{id:p.id,title:p.title,content:p.content,enabled:p.enabled,sort:p.sort,version:p.version}:{id:key(),title:'',content:'',enabled:false,sort:Math.min(9999,Math.max(0,...items.value.map(p=>p.sort))+10),version:0};await nextTick();titleInput.value?.focus()}
async function save(){if(!draft.value||busy.value)return;busy.value=true;error.value='';const {id,...payload}=draft.value;try{await api(`/admin/help-articles/${encodeURIComponent(id)}`,'PUT',payload);draft.value=null;await load();emit('notify','帮助内容已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function toggle(p:HelpArticle){if(busy.value)return;busy.value=true;error.value='';try{const {id,updated_at,...payload}=p;await api(`/admin/help-articles/${encodeURIComponent(id)}`,'PUT',{...payload,enabled:!p.enabled});await load();emit('notify',p.enabled?'帮助内容已下架':'帮助内容已发布')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(p:HelpArticle){if(busy.value)return;busy.value=true;error.value='';try{await api(`/admin/help-articles/${encodeURIComponent(p.id)}`,'DELETE',{version:p.version});deleting.value='';await load();emit('notify','帮助内容已删除')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>void load())
</script>
<template><section class="admin-help"><div class="help-toolbar"><div><h2>帮助中心</h2><p>共 {{items.length}} 条 · {{published}} 条已发布</p></div><div class="help-actions"><button class="secondary-button" :disabled="loading||busy||!!draft" @click="load"><RefreshCw :size="15"/>刷新</button><button class="primary-button" :disabled="loading||busy||!!draft" @click="edit()"><Plus :size="16"/>新增内容</button></div></div><p class="form-hint">已发布内容显示在前台帮助中心；排序值越小越靠前。保存后重新打开前台帮助中心即可查看。</p><div v-if="error" class="form-error" role="alert">{{error}}</div>
<section v-if="draft" class="surface help-editor"><div class="surface-heading"><h3>{{draft.version?'编辑帮助内容':'新增帮助内容'}}</h3><button class="icon-button" :disabled="busy" aria-label="关闭帮助编辑" @click="draft=null"><X :size="20"/></button></div><form class="form-stack" @submit.prevent="save"><fieldset :disabled="busy"><label>标题<input ref="titleInput" v-model="draft.title" required maxlength="80" placeholder="填写问题或帮助标题"/></label><label>内容<textarea v-model="draft.content" required maxlength="10000" rows="7" placeholder="填写详细说明，支持换行"/></label><div class="help-editor-options"><label>排序<input v-model.number="draft.sort" type="number" min="0" max="9999" step="1" required/></label><label class="checkbox-label"><input v-model="draft.enabled" type="checkbox"/>发布到帮助中心</label></div><div class="help-actions"><button type="button" class="secondary-button" @click="draft=null">取消</button><button type="submit" class="primary-button"><Save :size="16"/>{{busy?'保存中…':'保存内容'}}</button></div></fieldset></form></section>
<label class="help-search"><Search :size="17"/><input v-model="query" placeholder="搜索标题或内容" aria-label="搜索后台帮助内容"/></label><p v-if="loading" class="loading-line" role="status">正在加载帮助内容…</p><div v-else class="help-list"><article v-for="p in matches" :key="p.id" class="surface help-item"><div class="help-item-heading"><h3>{{p.title}}</h3><span class="badge" :class="p.enabled?'active':'disabled'">{{p.enabled?'已发布':'未发布'}}</span></div><p class="help-excerpt">{{p.content}}</p><div class="help-item-footer"><small>排序 {{p.sort}} · 更新于 {{datetime(p.updated_at)}}</small><div v-if="deleting!==p.id" class="help-actions"><button class="secondary-button" :disabled="busy||!!draft" @click="edit(p)">编辑</button><button class="secondary-button" :disabled="busy||!!draft" @click="toggle(p)">{{p.enabled?'下架':'发布'}}</button><button class="icon-button" :disabled="busy||!!draft" :aria-label="`删除帮助内容${p.title}`" @click="deleting=p.id"><Trash2 :size="17"/></button></div></div><div v-if="deleting===p.id" class="help-delete" role="alert"><p>确认删除“{{p.title}}”？删除后前台将不再显示，无法撤销。</p><div class="help-actions"><button class="secondary-button" :disabled="busy" @click="deleting=''">取消</button><button class="danger-button" :disabled="busy" @click="remove(p)">确认删除</button></div></div></article><div v-if="!matches.length&&!error" class="empty-state"><h3>{{query.trim()?'未找到相关内容':'暂无帮助内容'}}</h3><p>{{query.trim()?'请换个关键词搜索。':'点击“新增内容”添加常见问题和说明。'}}</p></div></div></section></template>
<style scoped>
.help-toolbar,.help-actions,.help-item-heading,.help-item-footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.help-toolbar{margin-bottom:12px}.help-toolbar h2{font-size:23px}.help-toolbar p{font-size:12px;color:#998da7;margin-top:8px}.help-actions{justify-content:flex-end;flex-shrink:0}.admin-help>.form-hint{margin-bottom:20px}.help-editor{margin:18px 0}.help-editor fieldset{border:0;padding:0;margin:0;min-width:0;display:flex;flex-direction:column;gap:16px}.help-editor-options{display:flex;align-items:center;gap:24px}.help-editor-options>label:first-child{max-width:180px}.help-search{display:flex;align-items:center;gap:10px;padding:12px 15px;margin:18px 0;border:1px solid #e5deef;background:white;border-radius:10px;color:#9988af;max-width:520px}.help-search input{background:transparent;border:0;outline:none;width:100%;min-width:0;color:#554b66;font-size:13px}.help-list{display:grid;gap:14px}.help-item{margin:0;padding:20px 24px;min-width:0}.help-item h3{overflow-wrap:anywhere;font-size:16px}.help-item-heading .badge{flex-shrink:0}.help-excerpt{white-space:pre-wrap;overflow-wrap:anywhere;color:#8c819a;font-size:13px;line-height:1.8;margin:12px 0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.help-item-footer small{font-size:11px;color:#a498ae}.help-item .secondary-button{padding:8px 14px;font-size:12px}.help-delete{margin-top:14px;padding-top:14px;border-top:1px solid #ece6f1;color:#b45163;font-size:13px;overflow-wrap:anywhere}.help-delete p{margin-bottom:12px}@media(max-width:640px){.help-toolbar,.help-item-footer{align-items:flex-start;flex-direction:column}.help-toolbar>.help-actions{width:100%;justify-content:flex-start}.help-item{padding:18px}.help-editor-options{align-items:flex-start;flex-direction:column;gap:14px}.help-item-footer{gap:14px}.help-item-heading{align-items:flex-start}}
</style>
